INSERT INTO public.leyes (id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave) VALUES ('f91cb735-e098-56f8-a0cf-4f84b36b196b', 'PODECOBI-DECRETO-M1', 'DECRETO por el que se modifica el diverso por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar.', 'decreto', '2025-07-31', 'https://sidof.segob.gob.mx/notas/docFuente/5764317', ARRAY['PODECOBI','Polos de Desarrollo Económico para el Bienestar']);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('35b2b032-af0a-5b92-a643-c5dd258e76fa', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 1, 'Preámbulo y considerandos', '<p>DECRETO por el que se modifica el diverso por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar.</p>
<p>Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Presidencia de la República.</p>
<p>CLAUDIA SHEINBAUM PARDO, Presidenta de los Estados Unidos Mexicanos, en ejercicio de la facultad que me confiere el artículo 89, fracción I, de la Constitución Política de los Estados Unidos Mexicanos, con fundamento en los artículos 31, 32 Bis, 33, 34, 38, 41 y 42 Ter de la Ley Orgánica de la Administración Pública Federal, 33 de la Ley de Planeación y 39, primer párrafo, fracción III, del Código Fiscal de la Federación, y</p>
<p>CONSIDERANDO</p>
<p>Que en términos del artículo 25, primer párrafo, de la Constitución Política de los Estados Unidos Mexicanos (CPEUM), corresponde al Estado la rectoría del desarrollo nacional para garantizar que este sea integral y sustentable, que fortalezca la Soberanía de la Nación y su régimen democrático y que, mediante la competitividad, el fomento al crecimiento económico, al empleo y una más justa distribución del ingreso y la riqueza, permita el pleno ejercicio de la libertad y la dignidad de los individuos, grupos y clases sociales, cuya seguridad protege la Constitución;</p>
<p>Que el último párrafo del artículo 25 de la CPEUM establece que las autoridades de los tres órdenes de gobierno deberán implementar políticas públicas que promuevan el bienestar general mediante la simplificación administrativa, la digitalización de trámites y servicios, el fortalecimiento de las capacidades tecnológicas públicas y la adopción de buenas prácticas regulatorias, a fin de contribuir al desarrollo;</p>
<p>Que el "Plan México", presentado por la Presidenta de los Estados Unidos Mexicanos el 13 de enero de 2025, tiene como principio la construcción de un Estado eficiente, transparente e innovador, mediante el fortalecimiento de las capacidades institucionales y la simplificación de los procesos administrativos para hacer más accesibles los servicios públicos, fomentar la inversión y fortalecer el Estado de derecho;</p>
<p>Que dentro de los objetivos del "Plan México" se encuentra ampliar el acceso a la educación media superior y superior, así como lograr anualmente la formación de 150 mil profesionistas y técnicos con formación continua alineada a sectores estratégicos y 100% de educación dual en media superior técnica, por lo que se requiere que las instituciones educativas cuenten con los elementos necesarios que les permita brindar la formación y capacitación actualizada y de calidad para atender los requerimientos de la industria nacional y lograr que la población alcance mayores niveles de bienestar y prosperidad compartida;</p>
<p>Que el Plan Nacional de Desarrollo 2025-2030 (PND), publicado en el Diario Oficial de la Federación (DOF) el 15 de abril de 2025, reconoce la importancia de fortalecer la coordinación entre los tres órdenes de gobierno para abatir las desigualdades regionales, promover el desarrollo equilibrado del país y consolidar un estado de bienestar, proponiendo un modelo que articule instrumentos de política económica, social, urbana y ambiental con un enfoque territorial;</p>
<p>Que el Eje Transversal 2 del PND denominado "Innovación pública para el desarrollo tecnológico nacional" tiene como objetivo dotar al Estado mexicano de capacidades físicas, tecnológicas y humanas para modernizar las funciones del Gobierno en sus tres niveles. Esto implica una transformación digital que simplifique y optimice los trámites gubernamentales, mejorando la calidad de los servicios tanto para la ciudadanía como para las empresas. La digitalización permitirá no solo una mejora en la eficiencia y accesibilidad de los servicios públicos, sino también un ahorro significativo de tiempo y recursos, todo ello en un marco de transparencia y eficacia en la gestión pública;</p>
<p>Que, el 22 de mayo de 2025, se publicó en el DOF el "Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar" (Decreto PODECOBI), el cual constituye una de las estrategias centrales del actual gobierno para incentivar procesos de transformación estructural en regiones con oportunidad de desarrollo económico, mediante la articulación de inversiones públicas y privadas, el desarrollo de infraestructura, la innovación productiva y la generación de empleo con enfoque territorial;</p>
<p>Que, con el fin de apoyar a las instituciones públicas de los tipos educativos medio superior y superior, así como para permitir la participación de la iniciativa privada en dicho sector, se propone que los contribuyentes y desarrolladores que realicen actividades económicas productivas en los Polos de Desarrollo Económico para el Bienestar y que celebren un contrato de comodato, en el que se conceda gratuitamente el uso de bienes nuevos de activo fijo a dichas instituciones, puedan aplicar el estímulo de gastos de capacitación. Este beneficio favorece la formación especializada de los estudiantes, así como la profesionalización de los trabajadores de los contribuyentes o desarrolladores;</p>
<p>Que la concesión gratuita del uso de bienes nuevos de activo fijo a las instituciones educativas, permitirá que los contribuyentes y desarrolladores puedan aplicar el estímulo de deducción inmediata de bienes nuevos de activo fijo, respecto de los bienes otorgados en comodato;</p>
<p>Que el otorgamiento de estos estímulos fiscales representa una acción concreta del Gobierno federal acorde con el compromiso prioritario de impulsar políticas públicas que fortalezcan la permanencia de las y los jóvenes en la educación media superior, aumenten los espacios en la educación superior, equipen la infraestructura educativa y faciliten la transición de los jóvenes al mercado laboral;</p>
<p>Que, con el fin de fortalecer el carácter técnico y colegiado del Comité Intersecretarial de Promoción y asegurar que las decisiones en torno a la operación de los polos cuenten con una visión estratégica de modernización institucional orientada a la eficiencia gubernamental y la mejora del entorno regulatorio, así como para simplificar y agilizar los trámites que sean indispensables para la instalación y desarrollo de las operaciones de dichos polos, se considera pertinente incorporar a la Agencia de Transformación Digital y Telecomunicaciones como integrante de dicho comité, ya que esta cuenta con las atribuciones para promover las soluciones tecnológicas para la digitalización de trámites y servicios, que permitan formular políticas en materia de simplificación administrativa, interoperabilidad institucional y atención ciudadana;</p>
<p>Que la educación media superior y superior ofrecen carreras técnicas que son clave para la transformación productiva del país y altamente valoradas por las industrias que se instalarán en los Polos de Desarrollo Económico para el Bienestar, por lo que, se considera conveniente que el Comité Intersecretarial de Promoción integre como invitado permanente a un representante de la Secretaría de Educación Pública. Con ello se garantizará una coordinación efectiva entre las políticas educativas y los procesos de desarrollo económico;</p>
<p>Que para lograr una implementación efectiva de los Polos de Desarrollo Económico para el Bienestar resulta indispensable fortalecer los mecanismos de coordinación intergubernamental que agilicen la realización de los trámites y las gestiones administrativas, salvaguardando en todo momento la competencia de cada una de las autoridades de los tres órdenes de gobierno;</p>
<p>Que se considera necesario habilitar medidas que permitan a los contribuyentes o desarrolladores que realicen actividades económicas al interior de los Polos de Desarrollo Económico para el Bienestar, acceder a un entorno normativo más ágil, simplificado y armonizado, que facilite la ejecución de los proyectos y el cumplimiento de sus obligaciones, sin menoscabo de los principios de seguridad de la población, la preservación del medio ambiente y la conservación de los recursos naturales;</p>
<p>Que para dar cumplimento a los objetivos del Decreto PODECOBI, se considera conveniente implementar una medida en la que la Secretaría de Economía y la Agencia de Transformación Digital y Telecomunicaciones, con la colaboración de las dependencias y entidades de la Administración Pública Federal competentes, las entidades federativas y los municipios en donde estén ubicados los Polos de Desarrollo Económico para el Bienestar, dentro del ámbito de su competencia, fomenten la facilitación y agilización de los trámites que se requieran para la instalación y desarrollo de las operaciones en dichos polos, y</p>
<p>Que, en ejercicio de la facultad establecida en el artículo 39, primer párrafo, fracción III del Código Fiscal de la Federación, he tenido a bien expedir el siguiente</p>', 'preambulo', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('ab2c8892-2308-5508-ab27-0a5acc0647dd', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 2, 'Artículo Único', '<p>DECRETO</p>
<p>Artículo Único. Se modifican los artículos Segundo, apartado A, fracción III; Cuarto, párrafo cuarto; Décimo, párrafo primero con adición; Décimo Tercero y se adicionan al artículo Cuarto los párrafos quinto, sexto y séptimo, recorriéndose los demás en su orden y al artículo Décimo los párrafos cuarto, quinto, sexto y séptimo, del "Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar", publicado en el Diario Oficial de la Federación el 22 de mayo de 2025, para quedar como sigue:</p>', 'ordinario', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('e58916c4-b8b3-58dd-bb21-b299528d17da', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 3, 'Artículo Segundo reformado', '<p>"Artículo Segundo. ...</p>
<p>A. ...</p>
<p>I. a II. ...</p>
<p>III. Contar con el Convenio de colaboración celebrado con la Secretaría de Educación Pública en materia de educación dual; el contrato de comodato celebrado con alguna institución pública de educación media superior o de educación superior; el Proyecto de inversión para el desarrollo de invenciones susceptibles de protección mediante patentes o el registro de modelos de utilidad; o bien, el Proyecto de inversión para la obtención de certificación inicial, según sea el caso; este requisito únicamente es aplicable para los efectos del estímulo fiscal previsto en el artículo Cuarto del presente decreto.</p>
<p>B. ...</p>
<p>...</p>', 'ordinario', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('b2e27074-aa20-586a-ab65-1dd043d9b8d6', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 4, 'Artículo Cuarto reformado', '<p>Artículo Cuarto. ...</p>
<p>I. a IV. ...</p>
<p>...</p>
<p>...</p>
<p>La deducción adicional por concepto de gastos de capacitación, sólo será procedente respecto de la capacitación proporcionada por los contribuyentes o los desarrolladores a sus trabajadores activos registrados ante el Instituto Mexicano del Seguro Social, siempre que dichos contribuyentes o desarrolladores cuenten con un programa de Educación dual autorizado por la Secretaría de Educación Pública o con un contrato de comodato celebrado con instituciones públicas de educación media superior o de educación superior, según sea el caso.</p>
<p>El contrato de comodato a que se refiere el párrafo anterior deberá cumplir con los siguientes requisitos:</p>
<p>I. Deberá celebrarse entre los contribuyentes o los desarrolladores, quienes tendrán la calidad de comodantes, e instituciones públicas de educación media superior o de educación superior, quienes tendrán el carácter de comodatarias.</p>
<p>II. Tendrá como objeto otorgar en comodato el uso de bienes nuevos de activo fijo.</p>
<p>III. Contener la descripción de los bienes nuevos de activo fijo.</p>
<p>IV. Tener una vigencia de por lo menos dos años a partir del otorgamiento del uso de los bienes nuevos de activo fijo.</p>
<p>V. Las instituciones públicas de educación media superior o de educación superior deberán contar con un programa educativo relacionado con las actividades económicas productivas que realicen los contribuyentes o las actividades de los desarrolladores al interior de los Polos de Desarrollo Económico para el Bienestar.</p>
<p>Los contribuyentes o desarrolladores que hayan celebrado el contrato de comodato podrán aplicar el estímulo fiscal establecido en el artículo Tercero de este decreto.</p>
<p>En el caso de que el contrato de comodato otorgue el uso de bienes de activo fijo que ya hubieran sido deducidos para efectos del impuesto sobre la renta, el estímulo a que se refiere el presente artículo sólo será procedente si la vigencia del citado contrato se celebra de manera indefinida.</p>
<p>...</p>
<p>...</p>
<p>...</p>', 'ordinario', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('ff4811f3-cf36-5a2e-be8e-f01fae11f2c5', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 5, 'Artículo Décimo reformado', '<p>Artículo Décimo. Para el establecimiento de los Polos de Desarrollo Económico para el Bienestar se crea un Comité Intersecretarial de Promoción integrado por un representante de la Secretaría de Economía quien presidirá dicho comité, y por un representante de las secretarías de Hacienda y Crédito Público, de Desarrollo Agrario, Territorial y Urbano, de Energía, de Medio Ambiente y Recursos Naturales y de la Agencia de Transformación Digital y Telecomunicaciones, quienes tendrán nivel mínimo de subsecretarios u homólogos. Serán invitados permanentes los representantes de la Secretaría de Educación Pública, de la Comisión Federal de Electricidad, de la Comisión Nacional del Agua y del Consejo Asesor de Desarrollo Económico Regional y Relocalización.</p>
<p>...</p>
<p>...</p>
<p>El Comité Intersecretarial de Promoción celebrará un convenio de coordinación para la facilitación de trámites administrativos con las entidades federativas y los municipios en los que se ubiquen los Polos de Desarrollo Económico para el Bienestar, en el ámbito de su competencia, con el fin de fomentar la facilitación y agilización de los trámites y las gestiones administrativas correspondientes para la instalación y operación de los referidos polos, de conformidad con lo dispuesto en la Ley de Planeación, y cumplir con los lineamientos que emita para tal efecto dicho comité.</p>
<p>La Secretaría de Economía y la Agencia de Transformación Digital y Telecomunicaciones, en colaboración con las diversas dependencias y entidades de la Administración Pública Federal competentes, así como las entidades federativas y los municipios, en las que se ubiquen los Polos de Desarrollo Económico para el Bienestar, en el ámbito de sus respectivas competencias, identificarán los trámites y las gestiones administrativas que los contribuyentes y los desarrolladores deben cumplir para realizar sus actividades en los referidos Polos de Desarrollo Económico para el Bienestar, clasificando aquellos que serán de cumplimiento obligatorio previo al inicio de sus actividades, así como aquellos cuyo cumplimiento pueda ser diferible, en términos de las disposiciones jurídicas aplicables. Dichos trámites y gestiones administrativas deben darse a conocer en el portal de Internet que el Gobierno de México habilite para tales efectos.</p>
<p>Para los efectos de este artículo, se consideran como trámites y gestiones administrativas, de manera enunciativa mas no limitativa, las licencias, autorizaciones, certificaciones, estudios, dictámenes, registros, entre otros, con excepción de los trámites y gestiones administrativas que se encuentren obligados a realizar los contribuyentes y desarrolladores ante el Servicio de Administración Tributaria, de conformidad con las disposiciones fiscales.</p>
<p>Tratándose de aquellos trámites y gestiones administrativas clasificados como diferibles, los contribuyentes y los desarrolladores deberán presentar un escrito libre que contenga la manifestación bajo protesta de decir verdad, que:</p>
<p>I. Acreditarán el cumplimiento de dichos trámites y gestiones administrativas en los términos y condiciones que se establezcan en los lineamientos que para tal efecto emita el Comité Intersecretarial de Promoción;</p>
<p>II. Serán responsables del cumplimiento de las disposiciones legales, reglamentarias y administrativas emitidas por las instancias federales, estatales o municipales, y</p>
<p>III. Conocen las sanciones y responsabilidades en que se incurre por presentar documentación y declarar datos falsos ante la autoridad correspondiente.</p>', 'ordinario', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('6a1a0451-a8d0-5ec8-8be7-ce68f86845d1', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 6, 'Artículo Décimo Tercero reformado', '<p>Artículo Décimo Tercero. El Servicio de Administración Tributaria debe emitir las reglas de carácter general necesarias para la debida y correcta aplicación de los estímulos fiscales establecidos en el presente decreto."</p>', 'ordinario', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('66f5733e-232d-5874-86f2-ad09a5ac9609', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 7, 'Transitorio Primero', '<p>TRANSITORIOS</p>
<p>PRIMERO. El presente decreto entra en vigor el día de su publicación en el Diario Oficial de la Federación.</p>', 'transitorio', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('394e4bde-c8fc-5baf-93cd-53ea554054e5', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 8, 'Transitorio Segundo', '<p>SEGUNDO. El Comité Intersecretarial de Promoción deberá emitir y publicar en el Diario Oficial de la Federación, las modificaciones al "Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar", publicado en el mismo órgano de difusión oficial el 22 de mayo de 2025, a fin de dar cumplimiento al presente decreto, en un plazo que no excederá de 30 días naturales, contado a partir de la publicación del presente decreto.</p>', 'transitorio', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('605d2920-978b-5c4b-af99-7b0abb3fe38a', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 9, 'Transitorio Tercero', '<p>TERCERO. Para los efectos del párrafo quinto del artículo Décimo del presente decreto en tanto no se habilite el portal de Internet al que hace referencia dicho artículo, los trámites y gestiones administrativas se darán a conocer en la página de Internet de la Secretaría de Economía, en lo que corresponde al ámbito federal, y en las páginas de Internet de las entidades federativas y de los municipios, en el ámbito local.</p>', 'transitorio', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('5e03d604-9e0b-5a15-aa74-9ad96543d09a', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 10, 'Transitorio Cuarto', '<p>CUARTO. Las erogaciones que se generen con motivo de la entrada en vigor del presente decreto, deben cubrirse con cargo al presupuesto aprobado para el presente ejercicio fiscal y subsecuentes de las dependencias y entidades competentes, toda vez que no se autorizarán ampliaciones al presupuesto regularizable de dichas dependencias y entidades.</p>', 'transitorio', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('0cbde49c-dbec-5144-8bc0-9e3c27f6e840', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 11, 'Firma del decreto', '<p>Dado en la Residencia del Poder Ejecutivo Federal, en Ciudad de México a 30 de julio de 2025.- Presidenta de los Estados Unidos Mexicanos, Claudia Sheinbaum Pardo.- Rúbrica.- Secretario de Hacienda y Crédito Público, Édgar Abraham Amador Zamora.- Rúbrica.- Secretaria de Medio Ambiente y Recursos Naturales, Alicia Isabel Adriana Bárcena Ibarra.- Rúbrica.- Secretaria de Energía, Luz Elena González Escobar.- Rúbrica.- Secretario de Economía, Marcelo Luis Ebrard Casaubon.- Rúbrica.- Secretario de Educación Pública, Mario Martín Delgado Carrillo.- Rúbrica.- Secretaria de Desarrollo Agrario, Territorial y Urbano, Edna Elena Vega Rangel.- Rúbrica.- Titular de la Agencia de Transformación Digital y Telecomunicaciones, José Antonio Peña Merino.- Rúbrica.</p>', 'complementario', 'PODECOBI-DECRETO-M1', 'Decreto modificatorio', NULL);
