INSERT INTO public.articulos (id, ley_id, identificador, tipo_articulo, contenido, orden) VALUES ('4bcc6ad3-eeb3-5af8-9bd9-be2a8895be90', 'ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a', 'Nota editorial · versiones relacionadas', 'complementario', '<p><a href="#ley-f91cb735-e098-56f8-a0cf-4f84b36b196b">Modificación 1 del decreto</a></p>', (SELECT COALESCE(MAX(orden),0)+1 FROM public.articulos WHERE ley_id='ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a'));
INSERT INTO public.articulos (id, ley_id, identificador, tipo_articulo, contenido, orden) VALUES ('01b3bf5d-914d-50f7-a784-8b2f24a84f92', 'f91cb735-e098-56f8-a0cf-4f84b36b196b', 'Nota editorial · versiones relacionadas', 'complementario', '<p><a href="#ley-ffa0dcbe-6f52-45da-bbbb-65f6410c2c9a">Texto original del decreto</a></p>', 0);
